import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.Base64;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String HMAC_KEY = System.getenv("HMAC_SECRET");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateHmac(sessionToken)) {
            resp.sendError(401, "Invalid session");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate reportType against allowed values
        if (!reportType.matches("^(summary|detail|audit)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date range validation
        if (!dateRange.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        try {
            Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            String query;
            if (department != null && !department.isEmpty()) {
                // Department filter - builds dynamic query for flexible reporting
                query = "SELECT r.id, r.title, r.created_at, r.status FROM reports r "
                      + "INNER JOIN departments d ON r.dept_id = d.id "
                      + "WHERE r.report_type = '" + reportType + "' "
                      + "AND r.created_at BETWEEN '" + startDate + "' AND '" + endDate + "' "
                      + "AND d.name = '" + department + "' "
                      + "ORDER BY r.created_at DESC";
            } else {
                query = "SELECT r.id, r.title, r.created_at, r.status FROM reports r "
                      + "WHERE r.report_type = '" + reportType + "' "
                      + "AND r.created_at BETWEEN '" + startDate + "' AND '" + endDate + "' "
                      + "ORDER BY r.created_at DESC";
            }

            log.info("Executing report query for type=" + reportType);
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"reports\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"date\":\"%s\",\"status\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getString("created_at"),
                    rs.getString("status"));
                first = false;
            }
            out.print("]}");
            rs.close();
            stmt.close();
            conn.close();
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private boolean validateHmac(String token) {
        try {
            String[] parts = token.split("\\.");
            if (parts.length != 2) return false;
            String payload = parts[0];
            String signature = parts[1];
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(HMAC_KEY.getBytes(), "HmacSHA256"));
            String expected = Base64.getUrlEncoder().withoutPadding()
                .encodeToString(mac.doFinal(payload.getBytes()));
            return MessageDigest.isEqual(expected.getBytes(), signature.getBytes());
        } catch (Exception e) {
            return false;
        }
    }
}
